# Public API (cm:*)
  @api cm:setContext(newTake)  @ 429-434
      @contract  setContext(nil) clears take+track; setContext(take) derives track via GetMediaItemTrack  @ 427
      @contract  refreshes all persisted caches (transient resets to {}) and fires configChanged {}  @ 428
  @api cm:clearTake()  @ 436-441
  @api cm:boundTake()  @ 444
      @contract  bound take pointer; nil when context is cleared (take/track tiers resolve off empty)  @ 443
  @api cm:boundTrack()  @ 447
      @contract  bound track pointer; nil when context is cleared (track tier resolves off empty)  @ 446
  @api cm:setTrack(newTrack)  @ 449-454
  @api cm:pollUndo()  @ 457
      @contract  delegates to the engine watcher; cm's watch group reloads tiers and fires configChanged  @ 456
  @api cm:isDeclared(key)  @ 494
      @contract  non-raising existence test against the schema; true iff key is declared  @ 493
  @api cm:get(key, opts)  @ 501-508
      -- pick is orthogonal to the merge mode: it indexes whatever that mode resolved, so only the
      -- one entry crosses the boundary. A nil pick is indistinguishable from none (see the spec).
  @api cm:getAt(level, key)  @ 511-520
      @contract  reads single tier only (no merge, no defaults); key nil → whole-cache clone  @ 510
  @api cm:valueFor(handle, scope, key)  @ 523-530
      @contract  single-tier value for a foreign take/track handle (ps:getAt); no merge or defaults  @ 522
  @api cm:defaultFor(key)  @ 533-536
      @contract  deep-copy of the schema default for key (no tiers, no merge); raises on unknown key  @ 532
  -- Writing
  @api cm:set(level, key, value)  @ 541-551
      @contract  deep-copies value into tier cache, persists, fires targeted configChanged  @ 540
  @api cm:remove(level, key)  @ 554-565
      @contract  removes key from named tier; no-op (no signal) if that tier's cache is unloaded  @ 553
  @api cm:assign(level, updates)  @ 568-582
      @contract  validates all keys before any write (all-or-nothing); REMOVE deletes; fires signal  @ 567

